contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    receive() external payable {}

    function run(uint lockTime_, uint amount) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);

        uint minSumBefore = c.MinSum();
        uint balanceBefore = address(this).balance;

        c.Initialized();

        // Set MinSum to 0 so Collect's MinSum check passes for any positive amount.
        c.SetMinSum(0);

        c.Put{value: amount}(lockTime_);

        (uint unlockTimeAfterPut, uint balanceAfterPut) = c.Acc(msg.sender);

        // Make the deciding call: Collect should succeed since minSum==0, balance>=amount,
        // and unlockTime <= block.timestamp.
        bool collectReverted = false;
        try c.Collect(amount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        (, uint balanceAfterCollect) = c.Acc(msg.sender);

        // General rule: if the deciding call did not revert, then the sender's recorded
        // balance after Collect is exactly the AfterPut balance minus amount (conservation
        // of deposited Ether), and the test contract has received the collected amount.
        assert(collectReverted == false
            ? balanceAfterCollect == balanceAfterPut - amount
                && address(this).balance == balanceBefore + amount
            : balanceAfterCollect == balanceAfterPut);
    }
}

