contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint a, uint b, uint initFlag) public payable {
        require(initFlag == 0 || initFlag == 1, "initFlag must be 0 or 1");

        // Pre-initialization setters: both should succeed and persist.
        c.SetMinSum(a);
        c.SetLogFile(address(this));
        uint minAfterSetters = c.MinSum();
        bool initialBefore = c.intitalized();

        bool initReverted = false;
        if (initFlag == 1) {
            try c.Initialized() {
                initReverted = false;
            } catch {
                initReverted = true;
            }
        } else {
            // Read-only call for the non-initializing branch.
            initialBefore; // silence unused variable warning
        }

        bool setMinReverted = false;
        try c.SetMinSum(b) {
            setMinReverted = false;
        } catch {
            setMinReverted = true;
        }

        bool setLogReverted = false;
        try c.SetLogFile(address(this)) {
            setLogReverted = false;
        } catch {
            setLogReverted = true;
        }

        uint minFinal = c.MinSum();
        bool initialFinal = c.intitalized();

        bool preInitSuccess = (!initialBefore && initFlag == 0);
        bool postInitSuccess = (initialBefore && initFlag == 1);

        assert(
            (minAfterSetters == a) &&
            ((preInitSuccess && !setMinReverted && !setLogReverted && minFinal == b && !initialFinal && !initReverted) ||
             (postInitSuccess && setMinReverted && setLogReverted && minFinal == a && initialFinal && !initReverted) ||
             (initFlag == 0 && minFinal == b && !initialFinal))
        );
    }

    receive() external payable {}
}

contract InvMutTest {
