        c = _c;
    }

    function run(uint a, uint b, uint initFirst) public payable {
        require(initFirst == 0 || initFirst == 1, "flag must be 0 or 1");

        if (initFirst == 1) {
            c.Initialized();
        }

        c.SetMinSum(a);
        uint minAfterFirst = c.MinSum();
        require(minAfterFirst == a, "first SetMinSum failed");

        bool reverted = false;
        try c.SetMinSum(b) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint minFinal = c.MinSum();

        if (initFirst == 1) {
            assert(reverted && minFinal == a);
        } else {
            assert(!reverted && minFinal == b);
        }
    }

    receive() external payable {}
}

