contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint putAmount, uint lockTime, uint collectAmount) public payable {
        require(putAmount > 0);
        require(lockTime > 0);
        require(collectAmount > 0);
        require(address(this).balance >= putAmount);

        // Put with a positive lock time so that unlockTime becomes block.timestamp + lockTime > 0.
        // This avoids the zero-lockTime path and the overflow trap in the first accepted-run
        // attempt: a zero lock time left unlockTime at 0, and the earlier failed test then
        // requested Collect while the account was still locked.
        c.Put{value: putAmount}(lockTime);

        (uint beforeUnlockTime, uint beforeBalance) = c.Acc(address(this));

        bool reverted;
        try c.Collect(collectAmount) { reverted = false; } catch { reverted = true; }

        (uint afterUnlockTime, uint afterBalance) = c.Acc(address(this));

        // General rule: if Collect succeeded, then the balance decreased by exactly the
        // requested amount and the unlock time did not increase.  If it reverted, nothing
        // observable about this account changed.  (We do not assert about the reverted case's
        // balance: a revert must preserve both stored fields, which the equality below captures.)
        assert(
            reverted
                ? afterBalance == beforeBalance && afterUnlockTime == beforeUnlockTime
                : afterBalance == beforeBalance - collectAmount && afterUnlockTime <= beforeUnlockTime
        );
    }

    receive() external payable {}
}

